<form class="client-row-form" method="post" action="<?= e(client_url('watchlist')) ?>" data-watchlist-form data-api-endpoint="<?= e(site_url('api/client/watchlist')) ?>" data-login-url="<?= e(site_url('login')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="<?= $watchlistSaved?'remove':'add' ?>"><input type="hidden" name="instrument_id" value="<?= e((string)$item['instrument_id']) ?>"><button type="submit"><?= $watchlistSaved?'Remove':'Add to watchlist' ?></button><span data-watchlist-message role="status"></span></form>
<br><a class="client-text-link" href="<?= e(client_url('trade').'?symbol='.rawurlencode((string)$item['symbol'])) ?>">Trade Demo ↗</a></td></tr><?php endforeach; ?>
</tbody></table></div><?php endif; ?>
